Now designing pass 2: a custom reward that guarantees within-group contrast (crash vs executes vs completes), on the easiest task (wipe), with an algorithmic pipeline note. Writing the reward file and spec.

```bash
mkdir -p specs rewards && cat > rewards/rewards_exec.py <<'EOF'
def _get(r, k, default=None):
    if isinstance(r, dict):
        return r.get(k, default)
    return getattr(r, k, default)

def reward(r):
    # 1.0 task completed
    # 0.0 program did not execute (crash / sandbox error)
    # 0.05 execution floor + 0.1 * shaped otherwise (executed but failed)
    tc = _get(r, "task_completed", False)
    if tc:
        return 1.0
    rc = _get(r, "sandbox_rc", 0)
    try:
        rc_i = int(rc)
    except Exception:
        rc_i = 0
    if rc_i != 0:
        return 0.0
    shaped = _get(r, "reward", 0.0)
    try:
        shaped = float(shaped)
    except Exception:
        shaped = 0.0
    return 0.05 + 0.1 * max(0.0, min(shaped, 1.0))
EOF
cat > specs/wipe1.json <<'EOF'
{
  "task": "wipe",
  "name": "wipe1",
  "steps": 30,
  "batch": 8,
  "lr": 2e-5,
  "reward": "rewards/rewards_exec.py",
  "note": "Write one executable program that: gets the observation; segments the brown spill with segment_sam3_text_prompt on the rgb image (if no mask is returned, fall back to point_prompt_molmo plus segment_sam3_point_prompt); back-projects the mask pixels to 3D with the camera intrinsics and transforms them to the world frame with the camera pose_mat (use the inverse of pose_mat if the resulting z is outside 0..0.3 m); computes the min and max x and y of the spill in world coordinates; then sweeps the end-effector back and forth over those bounds in small steps of at most 0.02 m, each move via solve_ik with orientation quaternion (0, 0, 1, 0) wxyz and z = 0.0 followed by move_to_joints.",
  "seed_start": 812000,
  "time": "12:00:00"
}
EOF
python3 -c "import ast; ast.parse(open('rewards/rewards_exec.py').read()); print('reward file OK')" && cat specs/wipe1.json
