"""retrain_min custom-reward hook for the CaP-X practice step (written into a call's recipe copy by fairsc3.submit_train when the
spec's reward is a file). The rollout runs exactly as in envs/capx/recipe/capx_reward.py (same /run request, same retries, same
service-fault and render-fault aborts); only the score differs: score = float(reward(result)) from the caller's file, where
`result` is the sim service's /run reply (keys: task_completed, reward (robosuite staged reward), sandbox_rc, seed, secs,
wall_s, log_tail, task). task_completed is always logged next to the score.
RMIN_REWARD_FILE = path of the caller's file (it defines reward(result) -> float)."""
import importlib.util, json, os, sys, time, urllib.request

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import capx_reward_of_record as _R   # the recipe's capx_reward.py, copied next to this file under this name

_FN = None


class Result(dict):
    """The /run reply; keys also readable as attributes (r["task_completed"] or r.task_completed). A missing attribute raises
    AttributeError, so getattr(r, k, default) and hasattr work (fair-sc-3 10-22: getattr(r, "success", None) raised KeyError)."""
    def __getattr__(self, k):
        try:
            return self[k]
        except KeyError:
            raise AttributeError(k) from None


def _fn():
    global _FN
    if _FN is None:
        spec = importlib.util.spec_from_file_location("rmin_reward", os.environ["RMIN_REWARD_FILE"])
        m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
        _FN = m.reward
    return _FN


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kw):
    ei = extra_info or {}
    body = json.dumps({"program": solution_str, "tag": f"idx{ei.get('index')}", "task": ei.get("task")}).encode()
    last = None
    for attempt in range(10):
        try:
            if attempt:
                _R._ROUTE.clear()
            req = urllib.request.Request(_R._url(ei.get("task")) + "/run", data=body, headers={"Content-Type": "application/json"})
