def reward(r):
    # completion-dominant: passing the task's own success check dwarfs merely
    # running, so GRPO concentrates mass on completing programs.
    tc = bool(r.get("task_completed"))
    try:
        rc = int(r.get("sandbox_rc", 0))
    except Exception:
        rc = 1
    try:
        sim = float(r.get("reward", 0.0))
    except Exception:
        sim = 0.0
    try:
