            _n[0] += 1
            _log({"tc": tc, "rc": rc, "sim": round(sim, 4), "seed": r.get("seed")})
    except Exception:
        pass
    if tc:
        return 1.0 + 0.05 * max(0.0, min(sim, 1.0))   # small coverage bonus among completions
    if rc != 0:
        return 0.0
    return 0.03 + 0.04 * max(0.0, min(sim, 1.0))      # ran-but-failed: far below 1.0
